    ('to', 'São Miguel do Tocantins', 'sao-miguel-do-tocantins', '1720200'),
    ('to', 'São Salvador do Tocantins', 'sao-salvador-do-tocantins', '1720259'),
    ('to', 'São Sebastião do Tocantins', 'sao-sebastiao-do-tocantins', '1720309'),
    ('to', 'São Valério', 'sao-valerio', '1720499'),
    ('to', 'Silvanópolis', 'silvanopolis', '1720655'),
    ('to', 'Sítio Novo do Tocantins', 'sitio-novo-do-tocantins', '1720804'),
    ('to', 'Sucupira', 'sucupira', '1720853'),
    ('to', 'Tabocão', 'tabocao', '1708254'),
    ('to', 'Taguatinga', 'taguatinga', '1720903'),
    ('to', 'Taipas do Tocantins', 'taipas-do-tocantins', '1720937'),
    ('to', 'Talismã', 'talisma', '1720978'),
    ('to', 'Tocantínia', 'tocantinia', '1721109'),
    ('to', 'Tocantinópolis', 'tocantinopolis', '1721208'),
    ('to', 'Tupirama', 'tupirama', '1721257'),
    ('to', 'Tupiratins', 'tupiratins', '1721307'),
    ('to', 'Wanderlândia', 'wanderlandia', '1722081'),
    ('to', 'Xambioá', 'xambioa', '1722107')
),
states AS (
  SELECT id, slug
  FROM locations
  WHERE type = 'state'
    AND status = 'active'
),
prepared AS (
  SELECT
    s.id AS state_id,
    cs.state_slug,
    cs.city_name,
    cs.city_slug,
    cs.ibge_code
  FROM city_seed cs
  JOIN states s
    ON s.slug = cs.state_slug
)
INSERT INTO locations (
  parent_id,
  type,
  slug,
  name,
  full_name,
  geographic_path,
  metadata,
  status
)
SELECT
  p.state_id AS parent_id,
  'city'::location_type AS type,
  p.city_slug AS slug,
  p.city_name AS name,
  p.city_name || ', ' || upper(p.state_slug) || ', Brasil' AS full_name,
  '/br/' || p.state_slug || '/' || p.city_slug AS geographic_path,
  jsonb_build_object(
    'ibge_code', p.ibge_code,
    'state_code', upper(p.state_slug),
    'country_code', 'BR',
    'seed_source', 'ibge_api',
    'center_latitude', 0,
    'center_longitude', 0,
    'coordinate_status', 'pending_geocode'
  ) AS metadata,
  'active'::location_status AS status
FROM prepared p
ON CONFLICT (geographic_path) DO UPDATE SET
  name = EXCLUDED.name,
  full_name = EXCLUDED.full_name,
  metadata = COALESCE(locations.metadata, '{}'::jsonb) || EXCLUDED.metadata,
  status = 'active',
  updated_at = now();
COMMIT;
